mapper.select:
SELECT bill_type AS tabFlag, count(id) AS count FROM stocktaking_profit_loss spl WHERE is_deleted=FALSE
${permissionSql}
GROUP BY bill_type

SELECT spl.id, spl.id AS mainId, spl.code, spl.source_id AS sourceId, spl.source_code AS sourceCode, spl.bill_type AS billType, spl.create_time AS createTime, spl.create_user_name AS createUserName, spl.approve_time AS approveTime, spl.approve_user_name AS approveUserName, spl.approve_status AS approveStatus, spld.sku_no AS skuNo, spld.sku_id AS skuId, spld.warehouse_id AS warehouseId, spld.warehouse_location AS warehouseLocation, spld.qty, spld.usable_qty AS usableQty, spld.frozen_qty AS frozenQty, spld.diff_qty AS diffQty, w.name AS warehouseName FROM stocktaking_profit_loss spl INNER JOIN stocktaking_profit_loss_detail spld ON spl.id=spld.main_id AND spld.is_deleted=FALSE LEFT JOIN warehouse w ON spld.warehouse_id=w.id AND w.is_deleted=FALSE WHERE spl.is_deleted=FALSE
AND spl.bill_type=#{billType}
AND (spl.source_id IN
#{sourceId}
OR spl.id IN
#{sourceId}
)
AND spl.code ILIKE concat('%', #{params.code} ,'%')
AND spl.source_code ILIKE concat('%', #{params.sourceCode} ,'%')
AND spl.approve_status IN
#{approveStatus}
AND spl.bill_type IN
#{billType}
AND spl.create_user_id IN
#{createUserId}
AND spl.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > spl.create_time
AND spl.approve_user_id IN
#{item}
AND spl.approve_time >= #{params.approveTimeList[0]} and (#{params.approveTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > spl.approve_time
AND spld.sku_no IN
#{skuNo}
AND spld.warehouse_id =#{params.warehouseId}
AND spld.warehouse_location ILIKE concat('%', #{params.warehouseLocation} ,'%')
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
spl.id,spld.create_time DESC

SELECT spl.id, spl.code, spl.source_id AS sourceId, spl.source_code AS sourceCode, spl.bill_type AS billType, spl.create_time AS createTime, spl.create_user_name AS createUserName, spl.approve_time AS approveTime, spl.approve_status AS approveStatus, spl.approve_user_name AS approveUserName, spld.sku_no AS skuNo, spld.sku_id AS skuId, spld.warehouse_id AS warehouseId, spld.warehouse_location AS warehouseLocation, spld.qty, spld.usable_qty AS usableQty, spld.frozen_qty AS frozenQty, spld.diff_qty AS diffQty, w.name AS warehouseName FROM stocktaking_profit_loss spl INNER JOIN stocktaking_profit_loss_detail spld ON spl.id=spld.main_id AND spld.is_deleted=FALSE LEFT JOIN warehouse w ON spld.warehouse_id=w.id AND w.is_deleted=FALSE WHERE spl.is_deleted=FALSE
AND spl.id IN
#{id}
AND spl.bill_type=#{billType}
AND (spl.source_id IN
#{sourceId}
OR spl.id IN
#{sourceId}
)
AND spl.code ILIKE concat('%', #{params.code} ,'%')
AND spl.source_code ILIKE concat('%', #{params.sourceCode} ,'%')
AND spl.bill_type IN
#{billType}
AND spl.create_user_id IN
#{createUserId}
AND spl.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > spl.create_time
AND spl.approve_time >= #{params.approveTimeList[0]} and (#{params.approveTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > spl.approve_time
AND spld.sku_no IN
#{skuNo}
AND spld.warehouse_id =#{params.warehouseId}
AND spld.warehouse_location =#{params.warehouseLocation}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
spl.id DESC

SELECT spl.id AS sourceId, spl.code AS sourceCode, spl.bill_date AS billDate, spld.id AS sourceDetailId, spld.diff_qty AS qty, spld.sku_id, spld.sku_no, spld.warehouse_id, spld.warehouse_location FROM stocktaking_profit_loss_detail spld LEFT JOIN stocktaking_profit_loss spl ON spld.main_id=spl.id AND spl.is_deleted=FALSE WHERE spld.is_deleted=FALSE
AND spl.id IN
#{id}
